using System.Runtime.InteropServices;

class EnvVarCheck
{
    /// <summary>
    /// Checks whether an environment variable exists in the process environment,
    /// even if its value is empty. Needed because .NET 9 on Linux returns null
    /// for empty env vars (previously returned "").
    /// </summary>
    static bool ExistsInEnvironment(string name)
    {
        if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
        {
            try
            {
                var environ = File.ReadAllText($"/proc/{Environment.ProcessId}/environ");
                return environ.Split('\0').Any(e => e == name + "=" || e.StartsWith(name + "="));
            }
            catch { return false; }
        }
        // On Windows/macOS the old behaviour is preserved
        return Environment.GetEnvironmentVariable(name) != null;
    }

    void CheckFlag()
    {

